import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.DW4RdtHL.js";const k=JSON.parse('{"title":"Deploy a Release","description":"","frontmatter":{},"headers":[],"relativePath":"sops/deploy-release.md","filePath":"sops/deploy-release.md","lastUpdated":null}'),l={name:"sops/deploy-release.md"};function r(n,e,o,h,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="deploy-a-release" tabindex="-1">Deploy a Release <a class="header-anchor" href="#deploy-a-release" aria-label="Permalink to &quot;Deploy a Release&quot;">​</a></h1><p><strong>Status:</strong> Active · <strong>Owner:</strong> Platform Team · <strong>Last updated:</strong> 2026-09-01</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Every change to the Acme Order Service ships through the same deployment pipeline: commit, CI, build image, deploy staging (10% canary), verify, deploy prod. This SOP describes how to run a release through that pipeline, how to watch each stage, and how to override the pipeline when it fails — the override path referenced by the architecture doc.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><ul><li><strong>In scope:</strong> deploying a release of the order service and its worker to staging and production.</li><li><strong>Out of scope:</strong> database migrations (run separately, ahead of the release they support), infrastructure changes, and the web client (shipped through the storefront pipeline).</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>The change is merged to <code>main</code> through a reviewed pull request.</li><li>CI is green on the merge commit.</li><li>You have deploy permission for the <code>orders</code> namespace (Kubernetes) or the staging host (Docker).</li><li>No other release or credential rotation is in flight.</li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li><strong>Confirm the release.</strong> Note the commit SHA and the image tag that CI produced. The image tag is the commit SHA; the registry is <code>registry.acme.example/order-service</code>.</li><li><strong>Watch CI and the build.</strong> Confirm the unit and integration test stages pass and the image is pushed to the registry.</li><li><strong>Deploy staging.</strong> The pipeline deploys the image to staging as a 10% canary. Watch the canary for at least 10 minutes.</li><li><strong>Run the smoke checks.</strong> The verify stage runs health endpoint checks and a synthetic order round-trip against the canary.</li><li><strong>Deploy prod.</strong> On a pass, the pipeline rolls the image out to production. Watch the rollout in the console.</li><li><strong>Verify.</strong> Complete the post-deploy verification checklist below.</li><li><strong>Close out.</strong> Post the release (commit SHA, image tag, time) in the #ops channel and mark the release ticket done.</li></ol><h2 id="deployment-variants" tabindex="-1">Deployment variants <a class="header-anchor" href="#deployment-variants" aria-label="Permalink to &quot;Deployment variants&quot;">​</a></h2><p>The deploy stage applies the image differently depending on the target environment. The two variants below are structurally identical; use the one that matches your target.</p><h3 id="kubernetes" tabindex="-1">Kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to &quot;Kubernetes&quot;">​</a></h3><p>Production runs the order service as a Deployment in the <code>orders</code> namespace. The pipeline updates the image tag and the cluster performs a rolling update with no downtime.</p><ol><li><p>Set the image on the Deployment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/order-service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  order-service=registry.acme.example/order-service:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li><li><p>Watch the rollout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/order-service</span></span></code></pre></div></li><li><p>Confirm the pods:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app=order-service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wide</span></span></code></pre></div><p><em>Watch for:</em> the rollout is complete when every new pod reports <code>Ready</code>; old pods terminate only after the new ones pass their readiness probes.</p></li></ol><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><p>Staging runs the order service as a Docker container on the staging host. The pipeline replaces the container; expect a brief gap (a few seconds) while the new container starts.</p><ol><li><p>Pull the target image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry.acme.example/order-service:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li><li><p>Stop the running container:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-service</span></span></code></pre></div></li><li><p>Start the new container:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry.acme.example/order-service:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><em>Watch for:</em> the new container logs <code>listening on :8080</code> before you proceed; the old container is removed only after the new one is up.</p></li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After the rollout completes, work through the post-deploy checklist:</p><ul><li>[ ] All pods/containers report healthy in the console</li><li>[ ] Health endpoint returns <code>200</code> on every replica</li><li>[ ] A synthetic order round-trip completes (<code>created</code> → <code>completed</code>)</li><li>[ ] Error rate is at baseline within 15 minutes</li><li>[ ] p99 latency on <code>POST /orders</code> is within 10% of the pre-release baseline</li><li>[ ] No new dead-letter queue entries since the rollout</li><li>[ ] The release is recorded in the release log with commit SHA and image tag</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>The pipeline rolls back automatically when the verify stage fails: it reverts to the last good image and re-queues the failed stage. Manual rollback is needed when the failure is caught after the verify stage — for example, a slow degradation in production.</p><div class="danger custom-block"><p class="custom-block-title">Abort criteria</p><p>Abort the rollout and roll back immediately if any of the following are observed during the canary or production rollout:</p><ul><li>Error rate on the gateway rises more than 2% above baseline</li><li>p99 latency on <code>POST /orders</code> doubles from baseline</li><li>The synthetic order round-trip fails twice in a row</li><li>Dead-letter queue depth grows for more than 5 minutes</li><li>Any replica fails its health check three times</li></ul></div><p>To roll back manually:</p><ol><li>Identify the last good image tag from the release log.</li><li>Re-run the deploy stage for that tag using the variant steps above (Kubernetes or Docker).</li><li>Watch the rollback rollout the same way you watched the original.</li><li>Complete the post-deploy verification checklist against the rolled- back version.</li><li>File a ticket describing the failure, with the time window, metrics, and logs, so the failed stage can be fixed and retried.</li></ol>`,26)])])}const g=i(l,[["render",r]]);export{k as __pageData,g as default};
